    async def accept_run(
        self,
        run_id: str,
        *,
        narrative: str | NotGiven = NOT_GIVEN,
        send_email: bool | NotGiven = NOT_GIVEN,
        email_address: str | NotGiven = NOT_GIVEN,
        email_language: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> InvestigatorDecision:
        """Accept a recommendation.

        Applies the recommended action through the item's normal path, so your usual webhooks fire. A `narrative` makes it edited and accepted. Restricted keys need the `decisions` scope (write); transaction alerts also need `transactions` (write). Escalating a verification or transaction opens a case.

        ``POST /v3/investigator/runs/{run_id}/accept/``

        Args:
          run_id
          narrative: A rewritten narrative. Sending one records the decision as edited and accepted.
          send_email: Email the person about the decision.
          email_address: Required when `send_email` is true.
          email_language
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "InvestigatorDecision",
            await self._client.request(
                "post",
                "/v3/investigator/runs/{run_id}/accept/",
                cast_to=InvestigatorDecision,
                path_params={"run_id": run_id},
                auth="api_key",
                body={
                    "narrative": narrative,
                    "send_email": send_email,
                    "email_address": email_address,
                    "email_language": email_language,
                },
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def override_run(
        self,
        run_id: str,
        *,
        action: Literal["approve", "decline", "escalate", "request"] | str,
        category: Literal[
            "missing_context", "needs_information", "policy_differs", "evidence_misread", "other"
        ]
        | str,
        reason: str,
        send_email: bool | NotGiven = NOT_GIVEN,
        email_address: str | NotGiven = NOT_GIVEN,
        email_language: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> InvestigatorDecision:
        """Override a recommendation.

        Takes another action with a category and a reason. Also overrides a decision the Investigator took on its own while it still stands. Restricted keys need the `decisions` scope (write); transaction alerts also need `transactions` (write). Escalating a verification or transaction opens a case.

        ``POST /v3/investigator/runs/{run_id}/override/``

        Args:
          run_id
          action
          category
          reason
          send_email: Email the person about the decision.
          email_address: Required when `send_email` is true.
          email_language
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "InvestigatorDecision",
            await self._client.request(
                "post",
                "/v3/investigator/runs/{run_id}/override/",
                cast_to=InvestigatorDecision,
                path_params={"run_id": run_id},
                auth="api_key",
                body={
                    "action": action,
                    "category": category,
                    "reason": reason,
                    "send_email": send_email,
                    "email_address": email_address,
                    "email_language": email_language,
                },
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

